  <script>
    // ── Mobile Nav Toggle ──
    const mobileToggle = document.getElementById('mobileToggle');
    const navLinks = document.getElementById('navLinks');
    mobileToggle.addEventListener('click', () => {
      navLinks.classList.toggle('open');
    });
    navLinks.querySelectorAll('a').forEach(a => {
      a.addEventListener('click', () => navLinks.classList.remove('open'));
    });

    // ── Product Carousel ──
    const track = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    const scrollAmount = 284; // card width + gap

    prevBtn.addEventListener('click', () => {
      track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });
    nextBtn.addEventListener('click', () => {
      track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });

    // Keyboard support for carousel
    document.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft') prevBtn.click();
      if (e.key === 'ArrowRight') nextBtn.click();
    });

    // ── Store Locator ──
    const mockStores = [
      { name: 'Fresh Pantry — Lincoln Park', address: '2140 N. Halsted St, Chicago, IL 60614', hours: '8am – 9pm Daily', distance: '0.8 mi' },
      { name: 'Fresh Pantry — Wicker Park', address: '1840 W. North Ave, Chicago, IL 60622', hours: '8am – 9pm Daily', distance: '1.4 mi' },
      { name: 'Fresh Pantry — Lakeview', address: '3745 N. Lincoln Ave, Chicago, IL 60613', hours: '8am – 9pm Daily', distance: '2.1 mi' }
    ];

    const zipInput = document.getElementById('zipInput');
    const storeSearchBtn = document.getElementById('storeSearchBtn');
    const storeResults = document.getElementById('storeResults');

    function renderStores() {
      const zip = zipInput.value.trim();
      if (!zip || zip.length < 5) {
        storeResults.innerHTML = '<div class="store-results-empty">Please enter a valid 5-digit zip code to search.</div>';
        return;
      }
      storeResults.innerHTML = mockStores.map(store => `
        <div class="store-result">
          <div class="store-icon">📍</div>
          <div class="store-details">
            <div class="store-name">${store.name}</div>
            <div class="store-address">${store.address}</div>
            <div class="store-hours">${store.hours}</div>
          </div>
          <div class="store-distance">${store.distance}</div>
        </div>
      `).join('');
    }

    storeSearchBtn.addEventListener('click', renderStores);
    zipInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') { e.preventDefault(); renderStores(); }
    });

    // ── Newsletter ──
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterConfirm = document.getElementById('newsletterConfirm');

    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const email = document.getElementById('emailInput').value.trim();
      if (email) {
        newsletterForm.style.display = 'none';
        newsletterConfirm.classList.add('show');
      }
    });

    // ── Scroll Animations (Intersection Observer) ──
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('animate-in');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1 });

    document.querySelectorAll('.section-title, .seasonal-card, .category-card, .highlight-item, .store-result').forEach(el => {
      el.style.opacity = '0';
      observer.observe(el);
    });
  </script>
